 /// Default-disabled, one-shot main-thread test commands. No game-file writes.
 internal sealed class ScriptedChecks:MonoBehaviour {
  private float _next;private string _last;private string _commandId,_commandOp;
  private static JArray Vector(Vector3 p)=>new JArray(p.x,p.y,p.z);
  private void Update(){if(!Plugin.Keys.EnableAutomation.Value||Time.unscaledTime<_next)return;_next=Time.unscaledTime+.2f;string path=Path.Combine(BepInEx.Paths.ConfigPath,"PeakCreativeMode.test-command.json");try{if(!File.Exists(path))return;var raw=File.ReadAllText(path);if(raw.Length>4096)return;var command=TestCommand.Parse(JObject.Parse(raw));if(command==null||command.Id==_last)return;_last=command.Id;_commandId=command.Id;_commandOp=command.Op;var ch=Character.localCharacter;var result=new JObject{["id"]=command.Id,["op"]=command.Op};if((!WorldDiagnostics.Playing(ch)&&!(command.Op=="handstate"&&ch!=null&&!ch.inAirport))||!Photon.Pun.PhotonNetwork.IsMasterClient||!Photon.Pun.PhotonNetwork.OfflineMode){result["error"]="Requires a live offline host avatar";Write(result);return;}
   switch(command.Op){case "throwat":{var target=new Vector3(command.Position.X,command.Position.Y,command.Position.Z);if(Vector3.Distance(ch.Center,target)>64)throw new Exception("Throw fixture too far away");var before=UnityEngine.Object.FindObjectsByType<Item>(FindObjectsSortMode.None).Select(i=>i.GetInstanceID()).ToHashSet();if(!PeakItemBridge.Spawn(Player.localPlayer,new PeakToken(33,"Native throw fixture",PeakItemBridge.Serialize(new ItemInstanceData(Guid.NewGuid()))),target-Vector3.right*2))throw new Exception("Cannot spawn throw fixture");var item=UnityEngine.Object.FindObjectsByType<Item>(FindObjectsSortMode.None).First(i=>!before.Contains(i.GetInstanceID()));item.RPC_SetThrownData(ch.photonView.ViewID,1);item.SetKinematic(false);item.rig.linearVelocity=Vector3.right*10;result["thrown"]=item.GetInstanceID();break;}case "explode":{var go=new GameObject("fixture explosion");go.transform.position=new Vector3(command.Position.X,command.Position.Y,command.Position.Z);var aoe=go.AddComponent<AOE>();aoe.auto=false;aoe.onEnable=false;aoe.range=5;aoe.knockback=25;aoe.mask=HelperFunctions.LayerType.TerrainMap;aoe.Explode();Destroy(go);result["exploded"]=true;break;}case "lightfire":{var map=UnityEngine.Object.FindAnyObjectByType<MapHandler>();Campfire fire=null;for(int i=0;map!=null&&i<map.segments.Length;i++){var root=MapHandler.GetCampfireRoot(i);var candidate=root!=null?root.GetComponentInChildren<Campfire>(true):null;if(candidate!=null&&(int)candidate.advanceToSegment==command.Size){fire=candidate;break;}}if(fire==null||!fire.gameObject.activeInHierarchy)throw new Exception("Campfire is not active");fire.GetComponent<Photon.Pun.PhotonView>().RPC("Light_Rpc",Photon.Pun.RpcTarget.All,true,0f);result["lit"]=command.Size;break;}case "campfires":{var map=UnityEngine.Object.FindAnyObjectByType<MapHandler>();var fires=new JArray();for(int i=0;map!=null&&i<map.segments.Length;i++){var root=MapHandler.GetCampfireRoot(i);if(root==null)continue;var fire=root.GetComponentInChildren<Campfire>(true);fires.Add(new JObject{["index"]=i,["segment"]=fire!=null?(int)fire.advanceToSegment:i,["pos"]=Vector(fire!=null?fire.transform.position:root.transform.position),["active"]=root.activeInHierarchy});}result["campfires"]=fires;break;}case "spawndump":result["spawns"]=SpawnAudit.Rows;break;case "openluggage":{int opened=0;foreach(var luggage in Luggage.ALL_LUGGAGE.Where(l=>l!=null&&!l.IsOpen).OrderBy(l=>(l.transform.position-ch.Center).sqrMagnitude)){luggage.GetComponent<Photon.Pun.PhotonView>().RPC("OpenLuggageRPC",Photon.Pun.RpcTarget.All,true);if(++opened>=command.Size)break;}result["opened"]=opened;break;}case "lightprobe":result["light"]=LightingProbe.Grid(command.Position);break;case "die":ch.photonView.RPC("RPCA_Die",Photon.Pun.RpcTarget.All);break;case "nativegive":if(!ItemDatabase.TryGetItem(command.ItemId,out var granola))throw new Exception("Missing granola");PeakItemBridge.Spawn(Player.localPlayer,new PeakToken(command.ItemId,"Native test item",PeakItemBridge.Serialize(new ItemInstanceData(Guid.NewGuid()))),ch.Center+ch.transform.forward);break;case "climb":AccessTools.Method(typeof(CharacterClimbing),"TryClimb").Invoke(ch.refs.climbing,new object[]{1.25f});break;case "handstate":break;case "terraform":result["requested"]=Terraformer.Instance.Request(command.Position,command.Size);break;case "disconnect":BridgeBehaviour.Instance.Client.Stop();break;case "connect":BridgeBehaviour.Instance.Client.Start();break;case "clip":NativeTerrainClipper.Instance.Prototype(command.Position);break;case "restore":NativeTerrainClipper.Instance.Restore();break;case "relay":GetComponent<PhotonRelayCheck>().Begin();break;case "warp":{var currentFeet=WorldDiagnostics.Feet(ch);var destination=WarpTarget.Center(command.Position,new V3(ch.Center.x,ch.Center.y,ch.Center.z),new V3(currentFeet.x,currentFeet.y,currentFeet.z));AccessTools.Method(typeof(Character),"WarpPlayer").Invoke(ch,new object[]{new Vector3(destination.X,destination.Y,destination.Z),false});break;}case "look":ch.data.lookValues=new Vector2(command.Yaw,-command.Pitch);AccessTools.Method(typeof(Character),"RecalculateLookDirections").Invoke(ch,null);break;case "injury":ch.refs.afflictions.AddStatus(CharacterAfflictions.STATUSTYPE.Injury,command.Amount);break;case "hunger":ch.refs.afflictions.AddStatus(CharacterAfflictions.STATUSTYPE.Hunger,command.Amount);break;}
   var hand=new JObject{["enabled"]=UnifiedHotbar.Enabled,["materializedSlot"]=UnifiedHotbar.Instance?.Hand.MaterializedSlot,["selected"]=ItemUI.Instance?.State.Selected,["stowed"]=ItemUI.Instance?.State.Stowed,["kind"]=UnifiedHotbar.Kind.ToString()};var native=new JArray();for(int k=0;k<3;k++)native.Add(PeakItemBridge.Read(k)?.ToJson());hand["native"]=native;var tokens=new JArray();for(int k=0;k<36;k++)if(ItemUI.Instance.State.Slots[k].Peak!=null)tokens.Add(new JObject{["slot"]=k,["peak"]=ItemUI.Instance.State.Slots[k].Peak.ToJson()});hand["tokens"]=tokens;result["handstate"]=hand;result["inventoryRaw"]=ItemUI.Instance.LastSnapshot;result["inventory"]=new JArray(ItemUI.Instance.State.Slots.Select(slot=>new JObject{["item"]=slot.Item,["count"]=slot.Count,["damage"]=slot.Damage,["maxDamage"]=slot.MaxDamage}));var cam=MainCamera.instance.transform;result["camera"]=new JObject{["pos"]=Vector(cam.position),["forward"]=Vector(cam.forward),["fov"]=MainCamera.instance.GetComponent<Camera>().fieldOfView,["mask"]=MainCamera.instance.GetComponent<Camera>().cullingMask};var heldMeshes=new JArray();foreach(var renderer in Resources.FindObjectsOfTypeAll<MeshRenderer>())if(renderer.name.StartsWith("MC held "))heldMeshes.Add(new JObject{["name"]=renderer.name,["active"]=renderer.gameObject.activeInHierarchy,["enabled"]=renderer.enabled,["layer"]=renderer.gameObject.layer,["pos"]=Vector(renderer.transform.position),["parent"]=renderer.transform.parent.name,["handPos"]=Vector(renderer.transform.parent.position),["handScale"]=Vector(renderer.transform.parent.lossyScale),["bounds"]=Vector(renderer.bounds.center),["size"]=Vector(renderer.bounds.size)});result["heldMeshes"]=heldMeshes;result["heldSwing"]=HeldItemRenderer.Instance?.SwingArc;var physical=new JArray();foreach(var item in Resources.FindObjectsOfTypeAll<Item>())if(item.gameObject.scene.IsValid()&&item.gameObject.activeInHierarchy&&item.data!=null)physical.Add(new JObject{["id"]=item.itemID,["guid"]=item.data.guid.ToString(),["pos"]=Vector(item.transform.position)});result["physicalPeak"]=physical;var database=new JArray();foreach(var entry in Zorro.Core.SingletonAsset<ItemDatabase>.Instance.itemLookup)database.Add(new JObject{["id"]=entry.Key,["name"]=entry.Value.name,["display"]=entry.Value.UIData.itemName});result["itemDatabase"]=database;
   var feet=WorldDiagnostics.Feet(ch);var supports=new JArray();foreach(var hit in Physics.RaycastAll(WorldDiagnostics.Feet(ch)+Vector3.up*.25f,Vector3.down,1,HelperFunctions.terrainMapMask,QueryTriggerInteraction.Ignore))if(hit.collider.GetComponentInParent<Character>()==null)supports.Add(new JObject{["name"]=hit.collider.name,["root"]=hit.collider.transform.root.name,["y"]=hit.point.y});result["support"]=supports;result["grounded"]=ch.data.isGrounded;result["climbing"]=ch.data.isClimbing;result["climbInput"]=new JObject{["primary"]=ch.input.usePrimaryIsPressed,["sincePress"]=ch.data.sincePressClimb,["sinceClimb"]=ch.data.sinceClimb,["blockedByHand"]=ClimbHandRule.Blocked(ch),["nativeCanClimb"]=ch.refs.climbing.CanClimb()};result["terraformStatus"]=Terraformer.Instance?.Status;result["terraformCount"]=Terraformer.Instance?.Confirmed;result["blockCount"]=BlockRenderer.Instance?.Grid.Count;result["clipProbe"]=NativeTerrainClipper.Instance?.Probe;result["clipStatus"]=NativeTerrainClipper.Instance?.Status;result["clipCacheBytes"]=NativeTerrainClipper.Instance?.CachePayloadBytes;result["relayCheck"]=PhotonRelayCheck.Result;result["mapSeed"]=BridgeBehaviour.Instance?.MapSeed;result["mobGroundFit"]=EntityRenderer.Instance?.Diagnostics;result["nativeHud"]=NativeHudLayout.Diagnostics?.DeepClone();result["worldSurvey"]=SpawnHintSampler.Diagnostics.DeepClone();result["boss"]=BossHud.Instance==null?null:new JObject{["id"]=BossHud.Instance.State.Id,["progress"]=BossHud.Instance.State.Progress,["visible"]=BossHud.Instance.State.Visible,["killed"]=BossHud.Instance.State.Killed,["victory"]=BossHud.Instance.VictoryVisible};result["frameMs"]=BlockRenderer.Instance?.AverageFrameMs;result["rebuildMs"]=BlockRenderer.Instance?.LastRebuildMs;result["feet"]=Vector(feet);result["center"]=Vector(ch.Center);result["look"]=new JArray(ch.data.lookValues.x,-ch.data.lookValues.y);result["effects"]=EffectLink.Diagnostics;result["injury"]=ch.refs.afflictions.GetCurrentStatus(CharacterAfflictions.STATUSTYPE.Injury);result["hunger"]=ch.refs.afflictions.GetCurrentStatus(CharacterAfflictions.STATUSTYPE.Hunger);result["held"]=InputMode.Instance?.Selected;var zones=new JArray();foreach(var zone in Resources.FindObjectsOfTypeAll<WaterZone>())if(zone!=null&&zone.isActiveAndEnabled){var bounds=zone.waterPlane!=null?zone.waterPlane.bounds:zone.zoneBounds;zones.Add(new JObject{["name"]=zone.name,["center"]=Vector(bounds.center),["size"]=Vector(bounds.size),["surface"]=zone.waterPlane!=null?bounds.center.y:bounds.max.y});}result["water"]=zones;
   var samples=new JArray();for(int x=-40;x<=40;x+=4)for(int z=-40;z<=40;z+=4){var origin=feet+new Vector3(x,48,z);var hits=Physics.RaycastAll(origin,Vector3.down,96,HelperFunctions.terrainMapMask,QueryTriggerInteraction.Ignore);Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var hit in hits)if(hit.collider.transform.root.name!="PeakMinecraftBlocks"&&!hit.collider.CompareTag("Water")){samples.Add(new JObject{["p"]=Vector(hit.point),["name"]=hit.collider.name});break;}}result["surfaces"]=samples;
   var geometry=new JArray();foreach(var collider in Resources.FindObjectsOfTypeAll<Collider>()){
    if(collider==null||!collider.enabled||!collider.gameObject.activeInHierarchy||collider.isTrigger||(HelperFunctions.terrainMapMask.value&(1<<collider.gameObject.layer))==0||collider.bounds.SqrDistance(feet)>80*80||collider.transform.root.name=="PeakMinecraftBlocks")continue;
    var entry=new JObject{["name"]=collider.name,["type"]=collider.GetType().Name,["layer"]=collider.gameObject.layer,["center"]=Vector(collider.bounds.center),["size"]=Vector(collider.bounds.size)};
    if(collider is MeshCollider mc&&mc.sharedMesh!=null){var mesh=mc.sharedMesh;entry["mesh"]=mesh.name;entry["readable"]=mesh.isReadable;entry["vertices"]=mesh.vertexCount;entry["submeshes"]=mesh.subMeshCount;var attrs=new JArray();foreach(var a in mesh.GetVertexAttributes())attrs.Add(a.ToString());entry["attributes"]=attrs;}
    var renderer=collider.GetComponent<MeshRenderer>();if(renderer!=null){entry["batched"]=renderer.isPartOfStaticBatch;entry["shader"]=renderer.sharedMaterial?.shader?.name;var filter=collider.GetComponent<MeshFilter>();if(filter?.sharedMesh!=null){entry["renderMesh"]=filter.sharedMesh.name;entry["renderReadable"]=filter.sharedMesh.isReadable;entry["renderVertices"]=filter.sharedMesh.vertexCount;}}
    geometry.Add(entry);
   }result["geometry"]=geometry;Write(result);Plugin.Log.LogInfo("[checks] "+command.Op+" "+command.Id);
  }catch(Exception e){Plugin.Log.LogWarning("[checks] "+e.Message);if(_commandId!=null)Write(new JObject{["id"]=_commandId,["op"]=_commandOp,["error"]=e.Message});}}
  private static void Write(JObject result)=>File.WriteAllText(Path.Combine(BepInEx.Paths.ConfigPath,"PeakCreativeMode.test-result.json"),result.ToString());
 }
